def _load_legacy_part(owner: str, source: str):
    ns = {"__name__": f"_bigcherry_merged_{owner}", "__file__": f"<merged:{owner}>"}
    exec(compile(source, ns["__file__"], "exec"), ns)
    found = ns.get("PATCHES")
    if found is None:
        single = ns.get("PATCH")
        found = [single] if single is not None else []
    return owner, list(found), tuple(ns.get("ENV_DOCS") or ())

_PARTS = (
    _load_legacy_part("1235_rd09_q81_activation_cache_foundation", "\"\"\"RD09 stage 1: per-graph Q8_1 activation-quantization cache -- foundation\nonly. No caller in mmvq.cu references this cache yet (that wiring is RD09\nstage 2, a separate future patch); this patch only adds the cache's own\nimplementation files to the HIP build and gives each ggml_backend_cuda_context\na place to own one cache instance. Until a caller exists, the added code is\nunreachable dead weight, so this patch cannot change any model output or\ntiming by construction -- the isolated bench for THIS patch is therefore\nexpected to show zero difference from bigcherry-native.\n\nRevised 2026-08-24 after dev-gpt-agent code review (session\nses_76b0fef0c94c434a, req_9bd7db08f19d4e53) of the first version of this\npatch (commit 4827a4fea70e2509a51c82326c037fbff84c4a58), which found two\nreal P1 issues before stage 2 could safely build on this foundation:\n  1. reserve()'s slab-boundary handling could return overlapping pointers\n     when a request didn't fit the tail of the current slab -- fixed by\n     making reserve() walk forward through existing slabs before ever\n     growing, instead of growing immediately on the first slab-boundary\n     miss.\n  2. The cache was a device-global singleton, weaker than the\n     context-scoped lifetime the design called for (upstream does not\n     guarantee one ggml_backend_cuda_context per device, so two contexts\n     sharing a device could otherwise race each other's\n     begin_generation() against still-live reservations) -- fixed by\n     moving ownership onto ggml_backend_cuda_context itself (an opaque\n     `void * q81_cache` member, constructed lazily on first use, destroyed\n     from the context's own destructor), which is what the two additional\n     anchored edits below (common.cuh, ggml-cuda.cu) exist for.\n\nProvenance (group 'rdna-boosts' patches are external backports; the\nmachine-readable PROVENANCE dict below is cross-checked against\nexternal-sources.toml by tools/tests/test_external_sources.py):\n\n  source:            stew675-rdna-boosts\n  repo:              https://github.com/stew675/llama.cpp\n  locator:           rdna-boosts (branch name is a locator only, NOT identity)\n  fork commit:       299f6eaf73b5eeb888bd94eaa66122d003136e6a\n                     (rebased v2 snapshot of \"CUDA: cache quantized Q8_1\n                     matmul inputs per graph\")\n  original commit:   ff6fde5046ffb86672e05da640d2bfb20d4bfdfc\n                     (pre-rebase; the plan item's own description cited only\n                     a truncated \"ff6fde5\", resolved to this full hash and\n                     verified content-identical to the v2 rebase via the v2\n                     snapshot's own patch-id audit, 2026-08-24)\n  reviewed snapshot: v2 -- head 9e46e1fdc7a880f9ae9a2f9a693ae3e14c142a22\n                     on base 4df29be4f4c3673f428170fda944a5b19f743bb8\n  plan item:         RD09 (docs/planning/active/rdna-boost-experiments/RD09.md)\n  mainline status:   NOT merged into ggml-org/llama.cpp master as of tip\n                     6d0549831 (same base check as RD19, 2026-08-18)\n\nWhat it does:\n  The fork's own commit is small (89 additions / 7 deletions across\n  common.cuh, ggml-cuda.cu, mmvq.cu) and NOT a verbatim port here: this\n  patch reimplements the same mechanism -- reuse one Q8_1 quantization of\n  an activation tensor across every MMVQ consumer that needs the identical\n  quantized data within the same graph evaluation, instead of\n  re-quantizing per node -- with two required adaptations found during\n  design review (dev-gpt-agent, session ses_76b0fef0c94c434a,\n  req_60a41664e0de43d6) that the fork's own implementation does not have:\n\n    1. Cache key includes the exact view data address/offset, not just the\n       view-root pointer plus shape/stride/stream. The fork's key omits the\n       offset, so two views of the SAME root tensor with identical\n       shape/stride but different byte offsets can collide there -- a real\n       false-hit bug in the source, not a hypothetical, and precisely the\n       failure mode this plan item's own risk statement (\"stale cache\n       entries could corrupt outputs\") warns against.\n    2. Backing storage is a bounded set of stable, NEVER-relocated slabs\n       (append a new slab on growth; existing slabs are never copied,\n       freed, or moved), not the fork's single arena that grows by\n       allocate-copy-free. HIP/CUDA graph capture bakes pointer values into\n       the captured graph; a relocating arena would silently corrupt every\n       subsequent replay once it needed to grow.\n\n  This stage adds only the cache's own implementation\n  (src/ggml/src/ggml-cuda/hip-q81-cache.{h,cpp}: generation-scoped\n  find/reserve/publish API, stable slab allocator, stats counters, the\n  GGML_HIP_Q8_1_CACHE_MODE=off|on|verify env gate) and wires the two new\n  files into the HIP backend's CMake build. It does not touch mmvq.cu, the\n  0200 dispatch hook, or any other live code path -- see \"What it does\n  NOT do yet\" below.\n\n  Fork-reported effect (gfx1201, unspecified model, decode-heavy workload):\n  not directly comparable here since this stage adds no caller; RD09's own\n  causal bench (stage 5 of the staged plan below) will measure real\n  quantize-launch reduction once stage 2 wires the cache into\n  ggml_cuda_mul_mat_vec_q().\n\nWhat it does NOT do yet (see docs/planning/active/rdna-boost-experiments/RD09.md\nfor the full 7-stage plan and its exit gates):\n  - Stage 2 (MMVQ integration): replace the current local Q8_1\n    materialization block in ggml_cuda_mul_mat_vec_q() (mmvq.cu, the single\n    existing call site of quantize_row_q8_1_cuda) with cache\n    find/reserve/publish calls. This is the change that would actually\n    alter model behavior if it had a bug -- deliberately isolated into its\n    own future patch so this foundation stage can be reviewed and tested\n    with zero behavioral risk.\n  - Stage 3 (adversarial correctness): the verify-mode byte-compare\n    harness and the full same-root/different-offset / cross-stream /\n    generation-boundary / capacity-exhaustion correctness matrix from the\n    plan item.\n  - Stage 4 (capture/topology): HIP graph warm-up/capture/replay\n    validation, dual-XTX tensor-split isolation.\n  - Stage 5 (causal bench): same-binary cache-off-vs-on A/B, quantize\n    launch counts, TG/PP/memory.\n\nPorting notes:\n  - Three vendor files are touched, all as pure additions (no existing\n    line is modified), so none of these can conflict with another patch's\n    edits to the same file:\n      * ggml/src/ggml-hip/CMakeLists.txt: adds the two new source files to\n        GGML_SOURCES_ROCM.\n      * ggml/src/ggml-cuda/common.cuh: adds one `void * q81_cache =\n        nullptr;` member to ggml_backend_cuda_context, right after its\n        destructor declaration. Deliberately an opaque pointer, not the\n        concrete ggml_hip_q81_cache type, so common.cuh does not need to\n        know about this cache's internals -- only hip-q81-cache.cpp\n        (which already includes common.cuh for the full context type)\n        ever dereferences it.\n      * ggml/src/ggml-cuda/ggml-cuda.cu: adds one\n        `#include \"ggml-cuda/hip-q81-cache.h\"` next to the existing\n        BigCherry-header include, and one call to\n        ggml_hip_q81_cache_destroy_for_context(*this) at the start of\n        ggml_backend_cuda_context's destructor body, before any of its\n        other teardown -- the cache never needs anything from later in\n        that destructor, so tearing it down first is always safe.\n  - The new files always compile in (no build-time flag): the\n    GGML_HIP_Q8_1_CACHE_MODE env var is a pure runtime toggle, defaulting\n    to off, and off must be byte-for-byte identical to the pre-cache\n    behavior. This is deliberate -- it is what makes the eventual stage 5\n    bench a true same-binary A/B (flip an env var, not rebuild) rather than\n    a cross-build comparison.\n\nIsolation and promotion (first-sweep policy, matches RD19's own convention):\n  - GROUP 'rdna-boosts' + STATE 'untested' keeps this OUT of the production\n    'framework' and 'validated-enhancements' patch-sets (both use exact\n    patch-id lists in recipes.toml). It is built ONLY when explicitly\n    selected:\n        python -m bigcherry apply --groups core,rdna-boosts \\\n                                  --states validated,untested\n  - Isolated test = bigcherry-native (framework only) bench vs this build\n    (framework + this patch). Since stage 1 adds no caller, the isolated\n    bench for THIS patch alone is a build-succeeds/host-tests-pass check,\n    not a performance comparison -- performance evidence arrives with\n    stage 2+.\n  - On eventual full-foundation promotion (after stage 6's exit gate):\n    set STATE = 'validated' and add this patch id to\n    [patch-set.validated-enhancements] in recipes.toml.\n\nMaintenance (future pin bumps / fork movement):\n  - Run `python -m bigcherry sources check` to detect: (a) the fork branch\n    moving or being rebased again, (b) this mechanism landing in mainline\n    (patch-id match against ff6fde5046ff... or 299f6eaf...), which would\n    make this patch redundant on the next pin bump, (c) content drift of\n    the fork commit vs the tracked snapshot.\n\"\"\"\n\nfrom bigcherry.patcher import Edit, FilePatch\n\nGROUP = \"rdna-boosts\"\nSTATE = \"validated\"\n\nPROVENANCE = {\n    \"source-id\": \"stew675-rdna-boosts\",\n    \"plan-item\": \"PRBE05\",\n    \"fork-commit\": \"299f6eaf73b5eeb888bd94eaa66122d003136e6a\",\n    \"fork-commit-title\": \"CUDA: cache quantized Q8_1 matmul inputs per graph\",\n    \"original-commit\": \"ff6fde5046ffb86672e05da640d2bfb20d4bfdfc\",\n    \"snapshot-head\": \"9e46e1fdc7a880f9ae9a2f9a693ae3e14c142a22\",\n    \"snapshot-base\": \"4df29be4f4c3673f428170fda944a5b19f743bb8\",\n    \"adaptations\": [\n        \"cache key strengthened with the exact view data address/offset \"\n        \"(the fork's key omits it, allowing a same-root/different-offset \"\n        \"false-hit collision)\",\n        \"backing storage reimplemented as bounded, never-relocated stable \"\n        \"slabs instead of the fork's relocatable grow-by-copy arena, for \"\n        \"HIP/CUDA graph-capture pointer stability\",\n        \"stage 1 (this patch) adds only the cache implementation with no \"\n        \"caller; the fork's commit wires straight into mmvq.cu in one \"\n        \"step, deliberately split here into a separate future stage 2 \"\n        \"patch so the zero-behavioral-risk foundation can be reviewed and \"\n        \"tested independently of the actual MMVQ integration\",\n    ],\n}\n\n_CMAKE_SOURCES_ANCHOR = (\n    r'file\\(GLOB   SRCS \"\\.\\./ggml-cuda/template-instances/mmf\\*\\.cu\"\\)\\n'\n    r'list\\(APPEND GGML_SOURCES_ROCM \\$\\{SRCS\\}\\)'\n)\n\n_CMAKE_SOURCES_NEW = \"\"\"\n    # bigcherry (RD09 stage 1): per-graph Q8_1 activation-quantization\n    # cache foundation. Always compiled in -- GGML_HIP_Q8_1_CACHE_MODE is a\n    # pure runtime toggle (default off, byte-for-byte identical to the\n    # pre-cache path), not a build-time flag, so a stage 2+ bench can be a\n    # same-binary A/B. No caller references this yet; see RD09.md.\n    list(APPEND GGML_SOURCES_ROCM\n        \"../ggml-cuda/hip-q81-cache.cpp\")\"\"\"\n\nCMAKE_PATCH = FilePatch(\n    path=\"ggml/src/ggml-hip/CMakeLists.txt\",\n    description=\"RD09 stage 1: add the Q8_1 activation cache foundation to the HIP source list\",\n    edits=(\n        Edit(\n            id=\"rd09-q81-cache-source\",\n            anchor=_CMAKE_SOURCES_ANCHOR,\n            rationale=\"the end of the GGML_SOURCES_ROCM glob block -- the same stable \"\n                      \"anchor 0100_cmake_options.py's own dispatch-sources edit uses, \"\n                      \"so this addition composes with it regardless of application order\",\n            text=_CMAKE_SOURCES_NEW,\n            guard=r\"hip-q81-cache\\.cpp\",\n        ),\n    ),\n)\n\n_CONTEXT_MEMBER_ANCHOR = r\"~ggml_backend_cuda_context\\(\\);\"\n\n_CONTEXT_MEMBER_NEW = \"\"\"\n\n    // bigcherry (RD09): opaque owner of this context's Q8_1 activation\n    // cache, if one has been constructed (lazily, on first use). Opaque\n    // so common.cuh does not need the concrete ggml_hip_q81_cache type --\n    // only hip-q81-cache.cpp, which already includes this header for the\n    // full ggml_backend_cuda_context definition, ever casts it back.\n    // Destroyed from this context's own destructor\n    // (ggml_hip_q81_cache_destroy_for_context, called from\n    // ggml-cuda.cu's ~ggml_backend_cuda_context()) -- never left to leak,\n    // and never torn down while the context itself is still alive.\n    void * q81_cache = nullptr;\"\"\"\n\nCOMMON_CUH_PATCH = FilePatch(\n    path=\"ggml/src/ggml-cuda/common.cuh\",\n    description=\"RD09 stage 1: give ggml_backend_cuda_context a place to own one Q8_1 cache instance\",\n    edits=(\n        Edit(\n            id=\"rd09-q81-cache-context-member\",\n            anchor=_CONTEXT_MEMBER_ANCHOR,\n            rationale=\"right after ggml_backend_cuda_context's own destructor declaration -- \"\n                      \"a stable, unique anchor inside the struct body\",\n            text=_CONTEXT_MEMBER_NEW,\n            guard=r\"q81_cache = nullptr;\",\n        ),\n    ),\n)\n\n_DESTRUCTOR_INCLUDE_ANCHOR = r'#include \"ggml-cuda/common\\.cuh\"'\n\n_DESTRUCTOR_INCLUDE_NEW = '\\n#include \"ggml-cuda/hip-q81-cache.h\"'\n\n_DESTRUCTOR_BODY_ANCHOR = (\n    r\"ggml_backend_cuda_context::~ggml_backend_cuda_context\\(\\) \\{\\n\"\n    r\"    std::unique_lock<std::mutex> lock\\(ggml_cuda_lock\\);\\n\"\n    r\"    ggml_cuda_lock_cv\\.wait\\(lock, \\[\\]\\{ return ggml_cuda_lock_counter\\.load\\(std::memory_order_relaxed\\) == 0; \\}\\);\"\n)\n\n_DESTRUCTOR_BODY_NEW = \"\"\"\n\n    // bigcherry (RD09): tear down this context's Q8_1 activation cache\n    // (if one was ever constructed) before any of the context's other\n    // teardown below -- the cache depends on nothing else this destructor\n    // frees, so destroying it first is always safe, and doing so early\n    // means an early-return teardown path can never accidentally skip it.\n    ggml_hip_q81_cache_destroy_for_context(*this);\"\"\"\n\nGGML_CUDA_CU_PATCH = FilePatch(\n    path=\"ggml/src/ggml-cuda/ggml-cuda.cu\",\n    description=\"RD09 stage 1: tear down the per-context Q8_1 cache from the context's own destructor\",\n    edits=(\n        Edit(\n            id=\"rd09-q81-cache-include\",\n            anchor=_DESTRUCTOR_INCLUDE_ANCHOR,\n            rationale=\"after the upstream common.cuh include at the top of the include block (an upstream line, so 1235 does not depend on 0830/1224 adding their telemetry header)\",\n            text=_DESTRUCTOR_INCLUDE_NEW,\n            guard=r'#include \"ggml-cuda/hip-q81-cache\\.h\"',\n        ),\n        Edit(\n            id=\"rd09-q81-cache-destructor\",\n            anchor=_DESTRUCTOR_BODY_ANCHOR,\n            rationale=\"the start of ggml_backend_cuda_context's destructor body, before its \"\n                      \"existing copy_event/streams/cublas_handles teardown\",\n            text=_DESTRUCTOR_BODY_NEW,\n            guard=r\"ggml_hip_q81_cache_destroy_for_context\\(\\*this\\);\",\n        ),\n    ),\n)\n\nPATCHES = [CMAKE_PATCH, COMMON_CUH_PATCH, GGML_CUDA_CU_PATCH]\n"),
    _load_legacy_part("1307_q81_activation_cache_mmvq", "\"\"\"1307 (PRBE05 / RD09 stage 2): wire 1235's Q8_1 activation cache into the MMVQ quantize step.\n\nFlash-Next decode is launch-gap bound (QFP13): ~183 quantize_q8_1 launches per generated token per GPU, one per\nMMVQ consumer, ~154 of them immediately followed by the matvec they feed. Several consumers read the same\nactivation (the GDN layer's qkv/gate/beta/alpha projections, shared-expert gate/up, routed experts), so the same\nvector is re-quantized per consumer. With GGML_HIP_Q8_1_CACHE_MODE=on, ggml_cuda_mul_mat_vec_q looks the quantized\nsrc1 up in 1235's generation-scoped cache (key: view root tensor, exact data address, stream, shape, strides) and\nskips the quantize launch on a hit; a miss quantizes into a stable cache slab and publishes it. Any reserve failure\nfalls back to the original per-call pool allocation and quantizer. A generation begins at every\nggml_backend_cuda_graph_compute, and slab growth is blocked while a HIP graph is being captured (1235's contract),\nso captured graphs only ever reference never-relocated slab memory. Requires 1235 (cache) and 1241 (anchor shape).\n\nDefault on (GGML_HIP_Q8_1_CACHE_MODE unset = on, changed 2026-10-05: a universally useful path is on by default,\nthe variable is the off switch); GGML_HIP_Q8_1_CACHE_MODE=off disables it. The default lives in the overlay parser\n(src/ggml/src/ggml-cuda/hip-q81-cache.cpp).\n\"\"\"\n\nfrom __future__ import annotations\n\nimport re\n\nfrom bigcherry.patcher import Edit, EnvDoc, FilePatch\n\nGROUP = \"rdna-boosts\"\nSTATE = \"validated\"\n\n_INCLUDE_ANCHOR = '#include \"mmvq.cuh\"\\n'\n_INCLUDE_TEXT = ('#if defined(GGML_USE_HIP)\\n'\n                 '#include \"hip-q81-cache.h\"  // bigcherry 1307: Q8_1 activation cache (1235)\\n'\n                 '#endif\\n')\n\n_QUANT_OLD = \"\"\"\\\n    const int64_t ne10_padded = GGML_PAD(ne10, MATRIX_ROW_PADDING);\n    ggml_cuda_pool_alloc<char> src1_q8_1(ctx.pool(), ne13*ne12 * ne11*ne10_padded * sizeof(block_q8_1)/QK8_1);\n    {\n        const int64_t s11 = src1->nb[1] / ts_src1;\n        const int64_t s12 = src1->nb[2] / ts_src1;\n        const int64_t s13 = src1->nb[3] / ts_src1;\n        quantize_row_q8_1_cuda(src1_d, nullptr, src1_q8_1.get(), src0->type, ne10, s11, s12, s13, ne10_padded, ne11, ne12, ne13, stream);\n    }\n\"\"\"\n\n_QUANT_NEW = \"\"\"\\\n    const int64_t ne10_padded = GGML_PAD(ne10, MATRIX_ROW_PADDING);\n    const size_t src1_q8_1_bytes = ne13*ne12 * ne11*ne10_padded * sizeof(block_q8_1)/QK8_1;\n    ggml_cuda_pool_alloc<char> src1_q8_1(ctx.pool());  // only allocated when the cache does not supply the buffer\n    const char * src1_q8_1_ptr = nullptr;\n    {\n        const int64_t s11 = src1->nb[1] / ts_src1;\n        const int64_t s12 = src1->nb[2] / ts_src1;\n        const int64_t s13 = src1->nb[3] / ts_src1;\n#if defined(GGML_USE_HIP)\n        // bigcherry 1307: reuse one Q8_1 quantization of src1 across every MMVQ consumer in this graph generation.\n        if (ggml_hip_q81_cache_mode_get() != GGML_HIP_Q81_CACHE_OFF) {\n            ggml_hip_q81_cache & q81 = ggml_hip_q81_cache_for_context(ctx);\n            // Identity is the consumed node itself, not its view root: an in-place op's result is a view of the\n            // same root at the same address and shape, so a root-based key would serve a stale quantization.\n            const ggml_hip_q81_cache_key key = ggml_hip_q81_cache_make_key(\n                q81, src1, src1->data, ctx.curr_stream_no,\n                ne10, ne10_padded, ne11, ne12, ne13, s11, s12, s13);\n            static const bool bigcherry_q81_trace = getenv(\"BIGCHERRY_Q81_TRACE\") != nullptr;\n            void * hit = ggml_hip_q81_cache_find(q81, key);\n            // A contiguous RESHAPE of a published node (e.g. Qwen4Exp hc_norm = reshape of the RMSNorm output)\n            // has identical Q8_1 bytes when neither layout needs row padding: the flatten is row-major and the\n            // 32-element groups line up. Look it up under the source node's own key (a reshape never changes data).\n            if (hit == nullptr && src1->op == GGML_OP_RESHAPE && src1->view_src != nullptr &&\n                    src1->data == src1->view_src->data && ggml_is_contiguous(src1) &&\n                    ggml_is_contiguous(src1->view_src) && ne10 == ne10_padded &&\n                    src1->view_src->ne[0] % MATRIX_ROW_PADDING == 0 &&\n                    ggml_nelements(src1) == ggml_nelements(src1->view_src)) {\n                const ggml_tensor * vs = src1->view_src;\n                const ggml_hip_q81_cache_key vkey = ggml_hip_q81_cache_make_key(\n                    q81, vs, vs->data, ctx.curr_stream_no, vs->ne[0], vs->ne[0], vs->ne[1], vs->ne[2], vs->ne[3],\n                    vs->ne[0], vs->ne[0]*vs->ne[1], vs->ne[0]*vs->ne[1]*vs->ne[2]);\n                hit = ggml_hip_q81_cache_find(q81, vkey);\n            }\n            // A contiguous RESHAPE that merges the source's dims 0 and 1 into a row that needs padding (Qwen4Exp GDN\n            // final_output): the producer (1312) publishes under the source node with exactly this consumer geometry.\n            if (hit == nullptr && src1->op == GGML_OP_RESHAPE && src1->view_src != nullptr &&\n                    src1->data == src1->view_src->data && ggml_is_contiguous(src1) &&\n                    ggml_is_contiguous(src1->view_src) && ne10 == src1->view_src->ne[0]*src1->view_src->ne[1] &&\n                    ggml_nelements(src1) == ggml_nelements(src1->view_src)) {\n                const ggml_hip_q81_cache_key fkey = ggml_hip_q81_cache_make_key(\n                    q81, src1->view_src, src1->data, ctx.curr_stream_no, ne10, ne10_padded, ne11, ne12, ne13, s11, s12, s13);\n                hit = ggml_hip_q81_cache_find(q81, fkey);\n            }\n            if (hit != nullptr) {\n                src1_q8_1_ptr = (const char *) hit;\n            } else {\n                if (bigcherry_q81_trace) {  // diagnose producer/consumer key mismatches (1309/1310)\n                    GGML_LOG_WARN(\"BIGCHERRY_Q81 miss gen=%llu src1=%p(%s op=%s view_of=%s) data=%p ne=%lld,%lld,%lld,%lld\\\\n\",\n                        (unsigned long long) ggml_hip_q81_cache_current_generation(q81), (const void *) src1, src1->name,\n                        ggml_op_name(src1->op), src1->view_src ? src1->view_src->name : \"-\", src1->data,\n                        (long long) ne10, (long long) ne11, (long long) ne12, (long long) ne13);\n                }\n                const ggml_hip_q81_cache_reservation r = ggml_hip_q81_cache_reserve(q81, src1_q8_1_bytes);\n                if (r.ok) {\n                    quantize_row_q8_1_cuda(src1_d, nullptr, r.ptr, src0->type, ne10, s11, s12, s13, ne10_padded, ne11, ne12, ne13, stream);\n                    ggml_hip_q81_cache_publish(q81, key, r);\n                    src1_q8_1_ptr = (const char *) r.ptr;\n                }\n            }\n        }\n#endif\n        if (src1_q8_1_ptr == nullptr) {\n            src1_q8_1.alloc(src1_q8_1_bytes);\n            quantize_row_q8_1_cuda(src1_d, nullptr, src1_q8_1.get(), src0->type, ne10, s11, s12, s13, ne10_padded, ne11, ne12, ne13, stream);\n            src1_q8_1_ptr = src1_q8_1.get();\n        }\n    }\n\"\"\"\n\n_SWITCH_OLD = \"        src0->data, src0->type, src1_q8_1.get(), ids_d, fusion_local, dst_d, ne00,\\n\"\n_SWITCH_NEW = \"        src0->data, src0->type, src1_q8_1_ptr, ids_d, fusion_local, dst_d, ne00,\\n\"\n\n_GEN_OLD = \"\"\"\\\nstatic enum ggml_status ggml_backend_cuda_graph_compute(ggml_backend_t backend, ggml_cgraph * cgraph) {\n    ggml_backend_cuda_context * cuda_ctx = (ggml_backend_cuda_context *) backend->context;\n\n    ggml_cuda_set_device(cuda_ctx->device);\n\"\"\"\n\n_GEN_NEW = \"\"\"\\\nstatic enum ggml_status ggml_backend_cuda_graph_compute(ggml_backend_t backend, ggml_cgraph * cgraph) {\n    ggml_backend_cuda_context * cuda_ctx = (ggml_backend_cuda_context *) backend->context;\n\n    ggml_cuda_set_device(cuda_ctx->device);\n#if defined(GGML_USE_HIP)\n    // bigcherry 1307: each graph evaluation is one Q8_1 activation-cache generation.\n    const bool bigcherry_q81_on = ggml_hip_q81_cache_mode_get() != GGML_HIP_Q81_CACHE_OFF;\n    if (bigcherry_q81_on) {\n        ggml_hip_q81_cache_begin_generation(ggml_hip_q81_cache_for_context(*cuda_ctx));\n        // Decode-shaped graph = every quantized matmul in it takes MMVQ (token count <= MMVQ_MAX_BATCH_SIZE);\n        // only then do Q8_1 producers publish (their output would otherwise be consumed by MMQ and wasted).\n        bool decode = true;\n        for (int i = 0; i < cgraph->n_nodes && decode; i++) {\n            const ggml_tensor * n = cgraph->nodes[i];\n            // only quantized-weight matmuls choose between MMVQ (reads the cache) and MMQ; f16/f32 matmuls such as\n            // QSA indexer scoring over the KV cells have large row counts in decode graphs too and must not count\n            if (n->src[0] == nullptr || n->src[1] == nullptr || !ggml_is_quantized(n->src[0]->type)) {\n                continue;\n            }\n            if (n->op == GGML_OP_MUL_MAT) {\n                decode = n->src[1]->ne[1] <= MMVQ_MAX_BATCH_SIZE;\n            } else if (n->op == GGML_OP_MUL_MAT_ID) {\n                decode = n->src[1]->ne[2] <= MMVQ_MAX_BATCH_SIZE;\n            }\n        }\n        ggml_hip_q81_decode_graph = decode;\n    }\n#endif\n\"\"\"\n\n_CAPTURE_OLD = \"        CUDA_CHECK(cudaStreamBeginCapture(cuda_ctx->stream(), cudaStreamCaptureModeRelaxed));\\n\"\n_CAPTURE_NEW = \"\"\"\\\n#if defined(GGML_USE_HIP)\n        if (bigcherry_q81_on) {  // bigcherry 1307: no slab growth while a graph is being captured\n            ggml_hip_q81_cache_set_capture_active(ggml_hip_q81_cache_for_context(*cuda_ctx), true);\n        }\n#endif\n\"\"\"\n\n_EVAL_OLD = (\"    ggml_cuda_graph_evaluate_and_capture(cuda_ctx, cgraph, use_cuda_graph, cuda_graph_update_required, graph_key);\\n\"\n             \"\\n    return GGML_STATUS_SUCCESS;\\n\")\n_EVAL_NEW = (\"    ggml_cuda_graph_evaluate_and_capture(cuda_ctx, cgraph, use_cuda_graph, cuda_graph_update_required, graph_key);\\n\"\n             \"#if defined(GGML_USE_HIP)\\n\"\n             \"    if (bigcherry_q81_on) {  // bigcherry 1307: capture (if any) has ended\\n\"\n             \"        ggml_hip_q81_cache_set_capture_active(ggml_hip_q81_cache_for_context(*cuda_ctx), false);\\n\"\n             \"    }\\n\"\n             \"#endif\\n\"\n             \"\\n    return GGML_STATUS_SUCCESS;\\n\")\n\nPATCHES = [\n    FilePatch(\n        path=\"ggml/src/ggml-cuda/mmvq.cu\",\n        description=\"1307: MMVQ reuses cached Q8_1 activations (1235 cache) instead of re-quantizing per consumer\",\n        language=\"none\",\n        edits=(\n            Edit(\n                id=\"q81-mmvq-include\",\n                anchor=re.escape(_INCLUDE_ANCHOR),\n                mode=\"insert_after\",\n                text=_INCLUDE_TEXT,\n                guard=r\"bigcherry 1307: Q8_1 activation cache\",\n                rationale=\"mmvq.cu's own header include; the cache API is HIP-only (1235 builds it for ggml-hip).\",\n                expect_matches=1,\n                max_span_lines=2,\n            ),\n            Edit(\n                id=\"q81-mmvq-quantize\",\n                anchor=re.escape(_QUANT_OLD),\n                mode=\"replace\",\n                text=_QUANT_NEW,\n                guard=r\"bigcherry 1307: reuse one Q8_1 quantization of src1\",\n                rationale=\"The single per-call src1 quantize in ggml_cuda_mul_mat_vec_q (after 1241's F32 early return).\",\n                expect_matches=1,\n                max_span_lines=9,\n            ),\n            Edit(\n                id=\"q81-mmvq-consumer\",\n                anchor=re.escape(_SWITCH_OLD),\n                mode=\"replace\",\n                text=_SWITCH_NEW,\n                guard=r\"src0->data, src0->type, src1_q8_1_ptr, ids_d\",\n                rationale=\"The one consumer of the quantized buffer in ggml_cuda_mul_mat_vec_q.\",\n                expect_matches=1,\n                max_span_lines=2,\n            ),\n        ),\n    ),\n    FilePatch(\n        path=\"ggml/src/ggml-cuda/ggml-cuda.cu\",\n        description=\"1307: per-graph-evaluation cache generation and capture-time growth block\",\n        language=\"none\",\n        edits=(\n            Edit(\n                id=\"q81-generation\",\n                anchor=re.escape(_GEN_OLD),\n                mode=\"replace\",\n                text=_GEN_NEW,\n                guard=r\"bigcherry 1307: each graph evaluation is one Q8_1 activation-cache generation\",\n                rationale=\"Head of ggml_backend_cuda_graph_compute: one generation per graph evaluation.\",\n                expect_matches=1,\n                max_span_lines=5,\n            ),\n            Edit(\n                id=\"q81-capture-begin\",\n                anchor=re.escape(_CAPTURE_OLD),\n                mode=\"insert_after\",\n                text=_CAPTURE_NEW,\n                guard=r\"bigcherry 1307: no slab growth while a graph is being captured\",\n                rationale=\"Immediately after cudaStreamBeginCapture in graph_compute (works with or without 1231's marker block).\",\n                expect_matches=1,\n                max_span_lines=2,\n            ),\n            Edit(\n                id=\"q81-capture-end\",\n                anchor=re.escape(_EVAL_OLD),\n                mode=\"replace\",\n                text=_EVAL_NEW,\n                guard=r\"bigcherry 1307: capture \\(if any\\) has ended\",\n                rationale=\"After evaluate_and_capture, which ends any capture it began.\",\n                expect_matches=1,\n                max_span_lines=4,\n            ),\n        ),\n    ),\n]\n\nENV_DOCS = (\n    EnvDoc('GGML_HIP_Q8_1_CACHE_MODE', 'off|on|verify', 'on',\n           'reuse one Q8_1 quantization of an activation across MMVQ consumers (foundation 1235); off disables it and the fusions that write it'),\n    EnvDoc('BIGCHERRY_Q81_TRACE', 'set', 'unset',\n           'log Q8_1 cache hits/misses'),\n)\n"),
    _load_legacy_part("1309_rms_norm_mul_q81", "\"\"\"1309 (PRBE06): fused RMSNorm*weight also produces the Q8_1 activation its MMVQ consumer needs.\n\nQFP13/PRBE06 Stage 0 (flashnext-v2-1308-census, 1307 + 1308 on): 29.9 rms_norm_f32<1024, true, ...> ->\nquantize_q8_1 -> mul_mat_vec_q triples per generated token per GPU - the fused RMS_NORM+MUL output is consumed by\nMMVQ and re-read only to be quantized. With GGML_HIP_Q8_1_CACHE_MODE=on (1307) and an eligible decode shape,\nggml_cuda_op_rms_norm_fused launches rms_norm_mul_q81_f32 instead: the same F32 result is still written (other\nconsumers, residual paths), and in the same launch each 32-column group is quantized with the native Q8_1 math\n(amax/127, roundf, half2(d, sum)) into a 1235 cache slab, published under exactly the key\nggml_cuda_mul_mat_vec_q builds for src1 == the MUL node. The MMVQ consumer then hits the cache and skips its\nquantize launch; any other consumer shape simply misses and quantizes as before. Q8_1 blocks are laid out as\nquantize_row_q8_1_cuda lays them (rows of GGML_PAD(ncols, MATRIX_ROW_PADDING), zero padding blocks), so a hit is\nbit-identical to the standalone quantization. Reservation failure (e.g. during graph capture) falls back to the\nunchanged kernel. Requires 1307 (cache wiring) and 1235 (cache).\n\nDefault on since 2026-10-05 (BIGCHERRY_RMS_Q81 unset = on); BIGCHERRY_RMS_Q81=0 disables.\n\"\"\"\n\nfrom __future__ import annotations\n\nimport re\n\nfrom bigcherry.patcher import Edit, EnvDoc, FilePatch\n\nGROUP = \"rdna-boosts\"\nSTATE = \"validated\"\n\n_INCLUDE_ANCHOR = '#include \"norm.cuh\"\\n'\n_INCLUDE_TEXT = ('#if defined(GGML_USE_HIP)\\n'\n                 '#include \"hip-q81-cache.h\"  // bigcherry 1309: Q8_1 activation cache (1235/1307)\\n'\n                 '#include <atomic>\\n'\n                 '#endif\\n')\n\n_KERNEL_ANCHOR = \"template <int block_size>\\nstatic __global__ void rms_norm_back_f32(\\n\"\n\n_KERNEL = r\"\"\"// bigcherry 1309 (PRBE06): RMSNorm * weight that also writes the Q8_1 blocks of its output (same layout and math\n// as quantize_row_q8_1_cuda, rows padded to ncols_padded with zero blocks). Each 32-column group is handled by 32\n// consecutive threads of one iteration, so the group reductions are width-32 warp reductions.\ntemplate <int block_size>\nstatic __global__ void rms_norm_mul_q81_f32(const float * x, const float * mul, float * dst, block_q8_1 * yq,\n        const int ncols, const int ncols_padded,\n        const int64_t stride_row, const int64_t stride_channel, const int64_t stride_sample,\n        const int64_t mul_stride_row, const int64_t mul_stride_channel, const int64_t mul_stride_sample,\n        const uint3 mul_ncols_packed, const uint3 mul_nrows_packed,\n        const uint3 mul_nchannels_packed, const uint3 mul_nsamples_packed, const float eps) {\n    static_assert(block_size % QK8_1 == 0, \"1309: block must cover whole Q8_1 groups\");\n    const int nrows     = gridDim.x;\n    const int nchannels = gridDim.y;\n    const int row       = blockIdx.x;\n    const int channel   = blockIdx.y;\n    const int sample    = blockIdx.z;\n    const int tid       = threadIdx.x;\n\n    const int64_t row_flat = ((int64_t) sample*nchannels + channel)*nrows + row;\n    x   += sample*stride_sample + channel*stride_channel + row*stride_row;\n    dst += row_flat*ncols;\n    yq  += row_flat*(ncols_padded/QK8_1);\n    mul += fastmodulo(sample, mul_nsamples_packed)*mul_stride_sample + fastmodulo(channel, mul_nchannels_packed)*mul_stride_channel\n         + fastmodulo(row, mul_nrows_packed)*mul_stride_row;\n\n    float tmp = 0.0f;\n    for (int col = tid; col < ncols; col += block_size) {\n        const float xi = x[col];\n        tmp += xi * xi;\n    }\n    extern __shared__ float s_sum[];\n    tmp = block_reduce<block_reduce_method::SUM, block_size>(tmp, s_sum);\n    const float scale = rsqrtf(tmp / ncols + eps);\n\n    for (int col = tid; col < ncols_padded; col += block_size) {  // uniform per 32-thread group\n        float v = 0.0f;\n        if (col < ncols) {\n            v = scale * x[col] * mul[fastmodulo(col, mul_ncols_packed)];\n            dst[col] = v;\n        }\n        const float amax = warp_reduce_max<QK8_1>(fabsf(v));\n        const float sum  = warp_reduce_sum<QK8_1>(v);\n        const float d    = amax / 127.0f;\n        const int   iqs  = col % QK8_1;\n        block_q8_1 & b   = yq[col / QK8_1];\n        b.qs[iqs] = amax == 0.0f ? 0 : (int8_t) roundf(v / d);\n        if (iqs == 0) {\n            b.ds = make_half2(d, sum);\n        }\n    }\n}\n\n\"\"\"\n\n_FUSED_CALL = \"    rms_norm_mul_f32_cuda(src0_d, mul_d, nullptr, dst_d,\\n\"\n\n_FUSED_GATE = r\"\"\"#if defined(GGML_USE_HIP)\n    // bigcherry 1309 (PRBE06): decode-shaped fused RMSNorm*weight also produces its Q8_1 activation into the 1307\n    // cache, keyed exactly as ggml_cuda_mul_mat_vec_q keys src1 == mul_tensor, so its MMVQ consumer skips the\n    // standalone quantize launch.\n    static const bool bigcherry_rms_q81 = getenv(\"BIGCHERRY_RMS_Q81\") == nullptr || atoi(getenv(\"BIGCHERRY_RMS_Q81\")) != 0;\n    if (bigcherry_rms_q81 && ggml_hip_q81_cache_mode_get() != GGML_HIP_Q81_CACHE_OFF && ne00 >= 1024 && ne00 % QK8_1 == 0 &&\n            ggml_hip_q81_decode_graph && ggml_is_contiguous(mul_tensor)) {  // decode-shaped graph (1307), not a row cap\n        const int64_t ne00_padded = GGML_PAD(ne00, MATRIX_ROW_PADDING);\n        const size_t  q8_bytes    = (size_t) (ne01*ne02*ne03) * (ne00_padded/QK8_1) * sizeof(block_q8_1);\n        ggml_hip_q81_cache & q81 = ggml_hip_q81_cache_for_context(ctx);\n        const ggml_hip_q81_cache_key key = ggml_hip_q81_cache_make_key(\n            q81, mul_tensor, mul_tensor->data, ctx.curr_stream_no,\n            ne00, ne00_padded, ne01, ne02, ne03, ne00, ne00*ne01, ne00*ne01*ne02);\n        if (ggml_hip_q81_cache_find(q81, key) == nullptr) {\n            const ggml_hip_q81_cache_reservation r = ggml_hip_q81_cache_reserve(q81, q8_bytes);\n            if (r.ok) {\n                const dim3 blocks_num(ne01, ne02, ne03);\n                const ggml_cuda_kernel_launch_params launch_params(blocks_num, dim3(1024, 1, 1), 32*sizeof(float), stream);\n                ggml_cuda_kernel_launch(rms_norm_mul_q81_f32<1024>, launch_params,\n                    src0_d, mul_d, dst_d, (block_q8_1 *) r.ptr, (int) ne00, (int) ne00_padded,\n                    s01, s02, s03, mul_s01, mul_s02, mul_s03,\n                    init_fastdiv_values(mul_ncols), init_fastdiv_values(mul_nrows),\n                    init_fastdiv_values(mul_nchannels), init_fastdiv_values(mul_nsamples), eps);\n                ggml_hip_q81_cache_publish(q81, key, r);\n                if (getenv(\"BIGCHERRY_Q81_TRACE\") != nullptr) {  // pair with 1307's miss trace\n                    GGML_LOG_WARN(\"BIGCHERRY_Q81 publish-rms gen=%llu node=%p(%s) data=%p ne=%lld,%lld,%lld,%lld\\n\",\n                        (unsigned long long) ggml_hip_q81_cache_current_generation(q81), (const void *) mul_tensor,\n                        mul_tensor->name, mul_tensor->data, (long long) ne00, (long long) ne01, (long long) ne02,\n                        (long long) ne03);\n                }\n                static std::atomic<bool> bigcherry_1309_logged{false};  // one context per GPU thread\n                if (getenv(\"BIGCHERRY_PATCH_TRACE\") != nullptr && !bigcherry_1309_logged.exchange(true)) {\n                    GGML_LOG_WARN(\"BIGCHERRY_PATCH_HIT patch=1309_rms_norm_mul_q81 ncols=%d rows=%d\\n\",\n                                  (int) ne00, (int) (ne01*ne02*ne03));\n                }\n                return;\n            }\n        }\n    }\n#endif\n\"\"\"\n\nPATCHES = [\n    FilePatch(\n        path=\"ggml/src/ggml-cuda/norm.cu\",\n        description=\"1309 (PRBE06): fused RMSNorm*weight emits the Q8_1 activation for its MMVQ consumer\",\n        language=\"none\",\n        edits=(\n            Edit(\n                id=\"rms-q81-include\",\n                anchor=re.escape(_INCLUDE_ANCHOR),\n                mode=\"insert_after\",\n                text=_INCLUDE_TEXT,\n                guard=r\"bigcherry 1309: Q8_1 activation cache\",\n                rationale=\"norm.cu's own header include; the cache API is HIP-only.\",\n                expect_matches=1,\n                max_span_lines=2,\n            ),\n            Edit(\n                id=\"rms-q81-kernel\",\n                anchor=re.escape(_KERNEL_ANCHOR),\n                mode=\"insert_before\",\n                text=_KERNEL,\n                guard=r\"static __global__ void rms_norm_mul_q81_f32\\(\",\n                rationale=\"Next to the RMSNorm kernels, before rms_norm_back_f32.\",\n                expect_matches=1,\n                max_span_lines=3,\n            ),\n            Edit(\n                id=\"rms-q81-dispatch\",\n                anchor=re.escape(_FUSED_CALL),\n                mode=\"insert_before\",\n                text=_FUSED_GATE,\n                guard=r\"bigcherry 1309 \\(PRBE06\\): decode-shaped fused RMSNorm\\*weight\",\n                rationale=\"ggml_cuda_op_rms_norm_fused's single launch (RMS_NORM+MUL without ADD); all of its \"\n                          \"strides and the mul broadcast shape are already computed above it.\",\n                expect_matches=1,\n                max_span_lines=2,\n            ),\n        ),\n    ),\n]\n\nENV_DOCS = (\n    EnvDoc('BIGCHERRY_RMS_Q81', '0|1', '1 (on)',\n           'fused RMS-norm*weight writes the Q8_1 activation directly (needs Q8_1 cache); 0 disables'),\n)\n"),
    _load_legacy_part("1310_act_q81", "\"\"\"1310 (QFP13): gated / plain activations also produce the Q8_1 activation their MMVQ consumer needs.\n\nQFP13 census (Flash-Next decode, per generated token per GPU): unary_gated_op_kernel -> quantize_q8_1 ~30 and\nunary_op_kernel -> quantize_q8_1 ~30, each followed by mul_mat_vec_q. Same pattern as 1309 (PRBE06): with\nBIGCHERRY_ACT_Q81=1 and GGML_HIP_Q8_1_CACHE_MODE=on (1307), an eligible F32 activation (row length a multiple of\nMATRIX_ROW_PADDING so the padded row equals the row, <= 16 rows, contiguous) launches bc_act_q81_kernel, which\nwrites the normal F32 result and, in the same launch, native-layout Q8_1 blocks into a 1235 cache slab published\nunder exactly the key ggml_cuda_mul_mat_vec_q builds for src1 == this node. The MMVQ consumer then skips its\nquantize launch; other consumers miss and quantize as before. Each 32-element group is 32 consecutive threads of\none block (block size and row length are multiples of 32), so group reductions are width-32 warp reductions and the\nQ8_1 math (amax/127, roundf, half2(d, sum)) matches quantize_q8_1 bit for bit. Reservation failure (e.g. during\ngraph capture) or an ineligible shape runs the unchanged kernel. Requires 1307.\n\nDefault on since 2026-10-05 (BIGCHERRY_ACT_Q81 unset = on); BIGCHERRY_ACT_Q81=0 disables.\n\"\"\"\n\nfrom __future__ import annotations\n\nimport re\n\nfrom bigcherry.patcher import Edit, EnvDoc, FilePatch\n\nGROUP = \"rdna-boosts\"\nSTATE = \"validated\"\n\n_INCLUDE_ANCHOR = '#include \"convert.cuh\"\\n'\n_INCLUDE_TEXT = ('#if defined(GGML_USE_HIP)\\n'\n                 '#include \"hip-q81-cache.h\"  // bigcherry 1310: Q8_1 activation cache (1235/1307)\\n'\n                 '#include <atomic>\\n'\n                 '#endif\\n')\n\n_HELPER_ANCHOR = \"template <float (*op)(float), typename T>\\nstatic __global__ void unary_op_kernel(const T * x, T * dst, const int k) {\\n\"\n\n_HELPER = r\"\"\"#if defined(GGML_USE_HIP)\n// bigcherry 1310: F32 activation (plain op(x) or gated op(x) * g) that also writes native-layout Q8_1 blocks of its\n// output. Threads run over the PADDED index space (rows x n_padded, n_padded = GGML_PAD(n, MATRIX_ROW_PADDING)),\n// exactly the layout quantize_row_q8_1_cuda produces: columns past n are zeros in Q8_1 and write no F32. The row\n// length must be a multiple of QK8_1 and the block size a multiple of QK8_1, so every 32-element group is 32\n// consecutive threads that are all in range together.\ntemplate <float (*op)(float), bool gated>\nstatic __global__ void bc_act_q81_kernel(const float * x, const float * g, float * dst, block_q8_1 * yq,\n        const int64_t k_padded, const int64_t n, const int64_t n_padded, const int64_t n_src, const int64_t o0,\n        const int64_t o1) {\n    const int64_t ip = int64_t(blockDim.x)*blockIdx.x + threadIdx.x;\n    if (ip >= k_padded) {\n        return;\n    }\n    const int64_t row = ip / n_padded;\n    const int64_t col = ip % n_padded;\n    float v = 0.0f;\n    if (col < n) {\n        const int64_t i = row * n + col;  // flat index of the contiguous F32 output\n        if constexpr (gated) {\n            // gate inputs may be strided per SOURCE row (n_src elements; n_src == n unless flattened, 1312)\n            const int64_t srow = i / n_src;\n            const int64_t scol = i % n_src;\n            const int64_t j0 = srow * o0 + scol;\n            const int64_t j1 = o0 == o1 ? j0 : srow * o1 + scol;\n            v = op(x[j0]) * g[j1];\n        } else {\n            v = op(x[i]);\n        }\n        dst[i] = v;\n    }\n    const int64_t i = ip;  // Q8_1 position in the padded layout\n    const float amax = warp_reduce_max<QK8_1>(fabsf(v));\n    const float sum  = warp_reduce_sum<QK8_1>(v);\n    const float d    = amax / 127.0f;\n    const int   iqs  = (int) (i % QK8_1);\n    block_q8_1 & b   = yq[i / QK8_1];\n    b.qs[iqs] = amax == 0.0f ? 0 : (int8_t) roundf(v / d);\n    if (iqs == 0) {\n        b.ds = make_half2(d, sum);\n    }\n}\n\n// Returns true when the activation was produced (F32 + Q8_1 published); false = caller runs the normal kernel.\ntemplate <float (*op)(float), bool gated>\n// flatten01 (1312): publish dims 0 and 1 merged into one row, the layout of a consumer that reads this node through a\n// contiguous reshape_3d(ne0*ne1, ne2, ne3) whose row needs MMVQ padding (1307's flattened-reshape lookup).\nstatic bool bc_act_q81_try(ggml_backend_cuda_context & ctx, ggml_tensor * dst, const float * x, const float * g,\n        const int64_t o0, const int64_t o1, const bool flatten01) {\n    static const bool enabled = getenv(\"BIGCHERRY_ACT_Q81\") == nullptr || atoi(getenv(\"BIGCHERRY_ACT_Q81\")) != 0;\n    if (!enabled || ggml_hip_q81_cache_mode_get() == GGML_HIP_Q81_CACHE_OFF || dst->type != GGML_TYPE_F32 ||\n            !ggml_is_contiguous(dst)) {\n        return false;\n    }\n    const int64_t ne0 = flatten01 ? dst->ne[0]*dst->ne[1] : dst->ne[0];\n    const int64_t ne1 = flatten01 ? dst->ne[2] : dst->ne[1];\n    const int64_t ne2 = flatten01 ? dst->ne[3] : dst->ne[2];\n    const int64_t ne3 = flatten01 ? 1 : dst->ne[3];\n    if (ne0 % QK8_1 != 0 || !ggml_hip_q81_decode_graph || (flatten01 && dst->ne[0] % QK8_1 != 0)) {  // only in decode-shaped graphs (1307): MMVQ consumers\n        return false;\n    }\n    const int64_t ne0_padded = GGML_PAD(ne0, MATRIX_ROW_PADDING);  // MMVQ's padded src1 row\n    ggml_hip_q81_cache & q81 = ggml_hip_q81_cache_for_context(ctx);\n    const ggml_hip_q81_cache_key key = ggml_hip_q81_cache_make_key(\n        q81, dst, dst->data, ctx.curr_stream_no, ne0, ne0_padded, ne1, ne2, ne3, ne0, ne0*ne1, ne0*ne1*ne2);\n    if (ggml_hip_q81_cache_find(q81, key) != nullptr) {\n        return false;\n    }\n    const int64_t k_padded = ne0_padded * ne1*ne2*ne3;\n    const ggml_hip_q81_cache_reservation r = ggml_hip_q81_cache_reserve(q81, (size_t) (k_padded / QK8_1) * sizeof(block_q8_1));\n    if (!r.ok) {\n        return false;\n    }\n    constexpr int block = 256;\n    static_assert(block % QK8_1 == 0, \"1310: block must cover whole Q8_1 groups\");\n    const ggml_cuda_kernel_launch_params launch_params((dim3) ((k_padded + block - 1) / block), dim3(block, 1, 1), 0, ctx.stream());\n    ggml_cuda_kernel_launch(bc_act_q81_kernel<op, gated>, launch_params, x, g, (float *) dst->data, (block_q8_1 *) r.ptr,\n                            k_padded, ne0, ne0_padded, dst->ne[0], o0, o1);\n    ggml_hip_q81_cache_publish(q81, key, r);\n    if (getenv(\"BIGCHERRY_Q81_TRACE\") != nullptr) {  // pair with 1307's miss trace\n        GGML_LOG_WARN(\"BIGCHERRY_Q81 publish-act gen=%llu node=%p(%s) data=%p ne=%lld,%lld,%lld,%lld\\n\",\n            (unsigned long long) ggml_hip_q81_cache_current_generation(q81), (const void *) dst, dst->name, dst->data,\n            (long long) ne0, (long long) ne1, (long long) ne2, (long long) ne3);\n    }\n    static std::atomic<bool> logged{false};\n    if (getenv(\"BIGCHERRY_PATCH_TRACE\") != nullptr && !logged.exchange(true)) {\n        GGML_LOG_WARN(\"BIGCHERRY_PATCH_HIT patch=1310_act_q81 gated=%d ne0=%lld rows=%lld\\n\", gated ? 1 : 0,\n                      (long long) ne0, (long long) (ne1*ne2*ne3));\n    }\n    return true;\n}\n#endif\n\n\"\"\"\n\n_UNARY_OLD = \"\"\"    } else {\n        unary_cuda<op>((const float *)src0_d, (float *)dst_d, ggml_nelements(src0), stream);\n    }\n\"\"\"\n_UNARY_NEW = \"\"\"    } else {\n#if defined(GGML_USE_HIP)\n        if (bc_act_q81_try<op, false>(ctx, dst, (const float *) src0_d, nullptr, 0, 0, false)) {  // bigcherry 1310\n            return;\n        }\n#endif\n        unary_cuda<op>((const float *)src0_d, (float *)dst_d, ggml_nelements(src0), stream);\n    }\n\"\"\"\n\n_GATED_OLD = \"\"\"        unary_gated_cuda<op>(src0_p, src1_p, (float *)dst_d, ggml_nelements(dst), nc, src0_o / sizeof(float), src1_o / sizeof(float), stream);\n\"\"\"\n_GATED_NEW = \"\"\"#if defined(GGML_USE_HIP)\n        if (bc_act_q81_try<op, true>(ctx, dst, src0_p, src1_p, src0_o / sizeof(float), src1_o / sizeof(float), false)) {  // bigcherry 1310\n            return;\n        }\n#endif\n        unary_gated_cuda<op>(src0_p, src1_p, (float *)dst_d, ggml_nelements(dst), nc, src0_o / sizeof(float), src1_o / sizeof(float), stream);\n\"\"\"\n\nPATCHES = [\n    FilePatch(\n        path=\"ggml/src/ggml-cuda/unary.cu\",\n        description=\"1310: F32 plain/gated activations emit the Q8_1 activation for their MMVQ consumer\",\n        language=\"none\",\n        edits=(\n            Edit(\n                id=\"act-q81-include\",\n                anchor=re.escape(_INCLUDE_ANCHOR),\n                mode=\"insert_after\",\n                text=_INCLUDE_TEXT,\n                guard=r\"bigcherry 1310: Q8_1 activation cache\",\n                rationale=\"unary.cu's convert.cuh include; the cache API is HIP-only.\",\n                expect_matches=1,\n                max_span_lines=2,\n            ),\n            Edit(\n                id=\"act-q81-helper\",\n                anchor=re.escape(_HELPER_ANCHOR),\n                mode=\"insert_before\",\n                text=_HELPER,\n                guard=r\"static bool bc_act_q81_try\\(\",\n                rationale=\"Before the plain unary kernel, so both ggml_cuda_op_unary and ggml_cuda_op_unary_gated \"\n                          \"(defined later) can call it.\",\n                expect_matches=1,\n                max_span_lines=3,\n            ),\n            Edit(\n                id=\"act-q81-unary\",\n                anchor=re.escape(_UNARY_OLD),\n                mode=\"replace\",\n                text=_UNARY_NEW,\n                guard=r\"bc_act_q81_try<op, false>\",\n                rationale=\"F32 branch of ggml_cuda_op_unary.\",\n                expect_matches=1,\n                max_span_lines=4,\n            ),\n            Edit(\n                id=\"act-q81-gated\",\n                anchor=re.escape(_GATED_OLD),\n                mode=\"replace\",\n                text=_GATED_NEW,\n                guard=r\"bc_act_q81_try<op, true>\",\n                rationale=\"F32 launch in ggml_cuda_op_unary_gated (after the swapped/split pointer setup).\",\n                expect_matches=1,\n                max_span_lines=2,\n            ),\n        ),\n    ),\n]\n\nENV_DOCS = (\n    EnvDoc('BIGCHERRY_ACT_Q81', '0|1', '1 (on)',\n           'activation ops write the Q8_1 activation directly for the next MMVQ (needs Q8_1 cache); 0 disables'),\n)\n"),
    _load_legacy_part("1311_hc_pre_q81", "\"\"\"1311 (QFP13): the hyper-connection pre-mix (GGML_OP_DSV4_HC_PRE) also produces its MMVQ consumer's Q8_1 input.\n\nBIGCHERRY_Q81_TRACE on Flash-Next profile v2 (flashnext-v2-q81c-trace) after 1307-1310: the largest remaining\nclass of Q8_1-cache misses is MMVQ consuming the output of dsv4_hc_pre_f32 (~2958 of ~8056 misses; census pair\nmul_mat_vec_q -> dsv4_hc_pre at ~30/token). Same mechanism as 1309/1310: with BIGCHERRY_HC_Q81=1 and\nGGML_HIP_Q8_1_CACHE_MODE=on (1307), an eligible pre-mix (contiguous F32 output, n_embd a multiple of QK8_1, <= 16\ntokens) launches dsv4_hc_pre_q81_f32, which computes the same weighted sum, writes the normal F32 result and, in\nthe same launch, native-layout Q8_1 blocks (rows padded to GGML_PAD(n_embd, MATRIX_ROW_PADDING), zero padding\nblocks, quantize_q8_1 math) into a 1235 cache slab published under the key ggml_cuda_mul_mat_vec_q builds for\nsrc1 == this node (1307's reshape-aware lookup also covers contiguous reshapes of it). Threads run over the padded\nindex space so each 32-element group is 32 consecutive threads. Ineligible shapes or a failed reservation launch\nthe unchanged kernel. Requires 1307.\n\nDefault on since 2026-10-05 (BIGCHERRY_HC_Q81 unset = on); BIGCHERRY_HC_Q81=0 disables. Only hyper-connection\nmodels have the op, so it is inert elsewhere.\n\"\"\"\n\nfrom __future__ import annotations\n\nimport re\n\nfrom bigcherry.patcher import Edit, EnvDoc, FilePatch\n\nGROUP = \"rdna-boosts\"\nSTATE = \"validated\"\n\n_INCLUDE_ANCHOR = '#include \"dsv4-hc.cuh\"\\n'\n_INCLUDE_TEXT = ('#if defined(GGML_USE_HIP)\\n'\n                 '#include \"hip-q81-cache.h\"  // bigcherry 1311: Q8_1 activation cache (1235/1307)\\n'\n                 '#include <atomic>\\n'\n                 '#endif\\n')\n\n_KERNEL_ANCHOR = \"template <bool has_comb>\\nstatic __global__ void dsv4_hc_post_f32(\\n\"\n\n_KERNEL = r\"\"\"#if defined(GGML_USE_HIP)\n// bigcherry 1311: dsv4_hc_pre_f32 over the PADDED output index space that also writes native-layout Q8_1 blocks.\n// Output must be contiguous ([n_embd, n_tokens]); columns past n_embd are Q8_1 zeros and write no F32.\ntemplate <bool gated>\nstatic __global__ void dsv4_hc_pre_q81_f32(\n        const float * x, const float * weights, float * dst, block_q8_1 * yq,\n        int64_t n_embd, int64_t n_embd_padded, int64_t hc, int64_t n_tokens,\n        int64_t sx0, int64_t sx1, int64_t sx2, int64_t sw0, int64_t sw1, int64_t sw2, float scale) {\n    const int64_t ip = (int64_t) blockIdx.x * blockDim.x + threadIdx.x;\n    if (ip >= n_embd_padded * n_tokens) {\n        return;\n    }\n    const int64_t it = ip / n_embd_padded;\n    const int64_t i0 = ip % n_embd_padded;\n    float v = 0.0f;\n    if (i0 < n_embd) {\n        float sum = 0.0f;\n        for (int64_t ih = 0; ih < hc; ++ih) {\n            const float xv = x[i0*sx0 + ih*sx1 + it*sx2];\n            float wv;\n            if constexpr (gated) {\n                wv = 1.0f / (1.0f + expf(-weights[i0*sw0 + ih*sw1 + it*sw2]));\n            } else {\n                wv = weights[ih*sw0 + it*sw1];\n            }\n            sum += xv * wv;\n        }\n        v = scale * sum;\n        dst[it*n_embd + i0] = v;\n    }\n    const float amax = warp_reduce_max<QK8_1>(fabsf(v));\n    const float qsum = warp_reduce_sum<QK8_1>(v);\n    const float d    = amax / 127.0f;\n    const int   iqs  = (int) (ip % QK8_1);\n    block_q8_1 & b   = yq[ip / QK8_1];\n    b.qs[iqs] = amax == 0.0f ? 0 : (int8_t) roundf(v / d);\n    if (iqs == 0) {\n        b.ds = make_half2(d, qsum);\n    }\n}\n#endif\n\n\"\"\"\n\n_LAUNCH_OLD = \"    auto kernel = gated ? dsv4_hc_pre_f32<true> : dsv4_hc_pre_f32<false>;\\n\"\n\n_LAUNCH_GATE = r\"\"\"#if defined(GGML_USE_HIP)\n    // bigcherry 1311: emit the Q8_1 activation for this node's MMVQ consumer into the 1307 cache.\n    {\n        static const bool bigcherry_hc_q81 = getenv(\"BIGCHERRY_HC_Q81\") == nullptr || atoi(getenv(\"BIGCHERRY_HC_Q81\")) != 0;\n        if (bigcherry_hc_q81 && ggml_hip_q81_cache_mode_get() != GGML_HIP_Q81_CACHE_OFF && ggml_is_contiguous(dst) &&\n                n_embd % QK8_1 == 0 && ggml_hip_q81_decode_graph && dst->ne[0] == n_embd && dst->ne[1] == n_tokens) {\n            const int64_t n_embd_padded = GGML_PAD(n_embd, MATRIX_ROW_PADDING);\n            ggml_hip_q81_cache & q81 = ggml_hip_q81_cache_for_context(ctx);\n            const ggml_hip_q81_cache_key key = ggml_hip_q81_cache_make_key(\n                q81, dst, dst->data, ctx.curr_stream_no, n_embd, n_embd_padded, n_tokens, dst->ne[2], dst->ne[3],\n                n_embd, n_embd*n_tokens, n_embd*n_tokens*dst->ne[2]);\n            if (ggml_hip_q81_cache_find(q81, key) == nullptr) {\n                const ggml_hip_q81_cache_reservation r = ggml_hip_q81_cache_reserve(\n                    q81, (size_t) (n_embd_padded * n_tokens / QK8_1) * sizeof(block_q8_1));\n                if (r.ok) {\n                    const dim3 qgrid((n_embd_padded * n_tokens + block_size - 1) / block_size, 1, 1);\n                    const ggml_cuda_kernel_launch_params qparams(qgrid, block_dims, 0, ctx.stream());\n                    auto qkernel = gated ? dsv4_hc_pre_q81_f32<true> : dsv4_hc_pre_q81_f32<false>;\n                    ggml_cuda_kernel_launch(qkernel, qparams,\n                        (const float *) x->data, (const float *) weights->data, (float *) dst->data, (block_q8_1 *) r.ptr,\n                        n_embd, n_embd_padded, hc, n_tokens,\n                        (int64_t) (nbx0 / sizeof(float)), (int64_t) (nbx1 / sizeof(float)), (int64_t) (nbx2 / sizeof(float)),\n                        (int64_t) (nbw0 / sizeof(float)), (int64_t) (nbw1 / sizeof(float)), (int64_t) (nbw2 / sizeof(float)),\n                        scale);\n                    ggml_hip_q81_cache_publish(q81, key, r);\n                    static std::atomic<bool> logged{false};\n                    if (getenv(\"BIGCHERRY_PATCH_TRACE\") != nullptr && !logged.exchange(true)) {\n                        GGML_LOG_WARN(\"BIGCHERRY_PATCH_HIT patch=1311_hc_pre_q81 n_embd=%lld tokens=%lld\\n\",\n                                      (long long) n_embd, (long long) n_tokens);\n                    }\n                    return;\n                }\n            }\n        }\n    }\n#endif\n\"\"\"\n\nPATCHES = [\n    FilePatch(\n        path=\"ggml/src/ggml-cuda/dsv4-hc.cu\",\n        description=\"1311: hyper-connection pre-mix emits the Q8_1 activation for its MMVQ consumer\",\n        language=\"none\",\n        edits=(\n            Edit(\n                id=\"hc-q81-include\",\n                anchor=re.escape(_INCLUDE_ANCHOR),\n                mode=\"insert_after\",\n                text=_INCLUDE_TEXT,\n                guard=r\"bigcherry 1311: Q8_1 activation cache\",\n                rationale=\"dsv4-hc.cu's own header include; the cache API is HIP-only.\",\n                expect_matches=1,\n                max_span_lines=2,\n            ),\n            Edit(\n                id=\"hc-q81-kernel\",\n                anchor=re.escape(_KERNEL_ANCHOR),\n                mode=\"insert_before\",\n                text=_KERNEL,\n                guard=r\"static __global__ void dsv4_hc_pre_q81_f32\\(\",\n                rationale=\"After dsv4_hc_pre_f32 and before dsv4_hc_post_f32.\",\n                expect_matches=1,\n                max_span_lines=3,\n            ),\n            Edit(\n                id=\"hc-q81-dispatch\",\n                anchor=re.escape(_LAUNCH_OLD),\n                mode=\"insert_before\",\n                text=_LAUNCH_GATE,\n                guard=r\"bigcherry 1311: emit the Q8_1 activation\",\n                rationale=\"ggml_cuda_op_dsv4_hc_pre's launch: shapes, strides, scale, block_size and block_dims are in scope.\",\n                expect_matches=1,\n                max_span_lines=2,\n            ),\n        ),\n    ),\n]\n\nENV_DOCS = (\n    EnvDoc('BIGCHERRY_HC_Q81', '0|1', '1 (on)',\n           'hyper-connection pre-mix writes the Q8_1 activation directly (needs Q8_1 cache); 0 disables'),\n)\n"),
    _load_legacy_part("1312_mul_q81", "\"\"\"1312 (QFP13): fused UNARY*MUL (sigmoid/silu gate) also produces the Q8_1 activation its MMVQ consumer needs.\n\nQFP13 Q8_1 miss trace after 1307-1311 (Flash-Next decode): two remaining quantize -> MMVQ chains per layer are fed by a\ngate multiply - the full-attention output gate (attn_gated = attn * sigmoid(gate) -> wo) and the GatedDeltaNet gated\noutput norm (rms_norm(x)*w * sigmoid(z) -> reshape final_output -> ssm_out). Upstream fuses each UNARY+MUL pair into\nggml_cuda_op_unary_mul (one unary_gated launch writing the MUL node), so neither ggml_cuda_op_unary_gated (1310) nor\nggml_cuda_op_mul ever runs for them. This patch routes the F32 branch of ggml_cuda_op_unary_mul_impl through 1310's\nbc_act_q81_try<op, true> with the MUL node as the output: same op(x) * g arithmetic (float multiply commutes, so\nMUL(g, op(x)) is bit-identical), plus MMVQ-padded native Q8_1 published under the key its MMVQ consumer looks up\n(1307's lookup resolves the final_output reshape to the MUL node). 1310's eligibility rules apply (BIGCHERRY_ACT_Q81=1,\ncache on, decode-shaped graph, row length a multiple of QK8_1, contiguous output); otherwise the unchanged launch runs.\nRequires 1310.\n\nDefault on since 2026-10-05 with 1310 (BIGCHERRY_ACT_Q81 unset = on).\n\"\"\"\n\nfrom __future__ import annotations\n\nimport re\n\nfrom bigcherry.patcher import Edit, EnvDoc, FilePatch\n\nGROUP = \"rdna-boosts\"\nSTATE = \"validated\"\n\n_IMPL_OLD = \"\"\"    } else {\n        unary_gated_cuda<op>((const float *) unary_src->data, (const float *) other_src->data,\n                             (float *) mul_node->data, k, nc,\n                             unary_stride / sizeof(float), other_stride / sizeof(float), stream);\n    }\n}\n\"\"\"\n\n_IMPL_NEW = \"\"\"    } else {\n#if defined(GGML_USE_HIP)\n        // GDN gated norm [head_v_dim, heads, T] is read by ssm_out through reshape_3d(head_v_dim*heads, T): publish\n        // that flattened layout when the per-head row would need MMVQ padding (1307 flattened-reshape lookup).\n        const bool flatten01 = mul_node->ne[0] % MATRIX_ROW_PADDING != 0 && mul_node->ne[1] > 1;\n        if (bc_act_q81_try<op, true>(ctx, mul_node, (const float *) unary_src->data, (const float *) other_src->data,\n                                     unary_stride / sizeof(float), other_stride / sizeof(float), flatten01)) {  // bigcherry 1312\n            return;\n        }\n#endif\n        unary_gated_cuda<op>((const float *) unary_src->data, (const float *) other_src->data,\n                             (float *) mul_node->data, k, nc,\n                             unary_stride / sizeof(float), other_stride / sizeof(float), stream);\n    }\n}\n\"\"\"\n\nPATCHES = [\n    FilePatch(\n        path=\"ggml/src/ggml-cuda/unary.cu\",\n        description=\"1312: fused UNARY*MUL gate emits the Q8_1 activation for its MMVQ consumer (via 1310)\",\n        language=\"none\",\n        edits=(\n            Edit(\n                id=\"unary-mul-q81\",\n                anchor=re.escape(_IMPL_OLD),\n                mode=\"replace\",\n                text=_IMPL_NEW,\n                guard=r\"bc_act_q81_try<op, true>\\(ctx, mul_node,\",\n                rationale=\"F32 launch at the end of ggml_cuda_op_unary_mul_impl; 1310's helper is defined earlier in unary.cu.\",\n                expect_matches=1,\n                max_span_lines=7,\n            ),\n        ),\n    ),\n]\n\nENV_DOCS = (\n    EnvDoc('BIGCHERRY_ACT_Q81', '0|1', '1 (on)',\n           'also covers the elementwise MUL -> Q8_1 path (shared with 1310)'),\n)\n"),
)

